export const getSearchPlatformsUrl = (params?: SearchPlatformsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/platforms/search?${stringifiedParams}` : `/api/platforms/search`
}

/**
 * @summary Search platforms by name or category
 */
export const searchPlatforms = async (params?: SearchPlatformsParams, options?: RequestInit): Promise<Platform[]> => {

  return customFetch<Platform[]>(getSearchPlatformsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getSearchPlatformsQueryKey = (params?: SearchPlatformsParams,) => {
    return [
    `/api/platforms/search`, ...(params ? [params] : [])
    ] as const;
    }


export const getSearchPlatformsQueryOptions = <TData = Awaited<ReturnType<typeof searchPlatforms>>, TError = ErrorType<unknown>>(params?: SearchPlatformsParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof searchPlatforms>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getSearchPlatformsQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof searchPlatforms>>> = ({ signal }) => searchPlatforms(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof searchPlatforms>>, TError, TData> & { queryKey: QueryKey }
}

export type SearchPlatformsQueryResult = NonNullable<Awaited<ReturnType<typeof searchPlatforms>>>
export type SearchPlatformsQueryError = ErrorType<unknown>


/**
 * @summary Search platforms by name or category
 */

export function useSearchPlatforms<TData = Awaited<ReturnType<typeof searchPlatforms>>, TError = ErrorType<unknown>>(
 params?: SearchPlatformsParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof searchPlatforms>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getSearchPlatformsQueryOptions(params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return { ...query, queryKey: queryOptions.queryKey };
}







